# Adds the Q1 revision-2 results (deblending, velocity/window systematics, disk recovery model, RADEX, Soutflow variants) to /output/report.json.
# Idempotent: entries tagged 'Q1b:' are replaced. Run after build_report_q1.py. All numbers are read from out/q1/*.csv where practical.
import json,numpy as np,pandas as pd
O='/workspace/out/q1/'
r=json.load(open('/output/report.json'))
A=lambda n,v,u=None:{'name':n,'value':v,**({'unit':u} if u else {})}
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q1b:')]
r['recipe']=[x for x in r['recipe'] if not x['description'].startswith('Q1b:')]
def add(q,v,c,ev,t=None,u=None,ass=None):
    d={'quantity':'Q1b: '+q,'value':v,'confidence':c,'evidence':ev}
    if t:d['target']=t
    if u:d['uncertainty']=u
    if ass:d['assumptions']=ass
    r['results'].append(d)
S=pd.read_csv(O+'q1_deblend_summary.csv'); LX=pd.read_csv(O+'q1_deblend_ladders_xb4f.csv'); NS0=pd.read_csv(O+'q1_deblend_NS_contrast.csv'); NS=pd.concat([NS0[(NS0.quantity.str.contains('2-1'))&(NS0.model=='nomissing')],NS0[(NS0.quantity.str.contains('4-3'))&(NS0.model=='nomissing')]]).reset_index(drop=True); CB=pd.read_csv(O+'q1_deblend_contrast_bias.csv')
def sv(comp,q,model='nomissing',col='value'):
    x=S[(S.model==model)&(S.comp==comp)&(S.quantity.str.startswith(q))]; return x.iloc[0] if len(x) else None
def fmt(x,d=2): return f'{x:.{d}f}'
def rng(x): return f'{x.value:.2f} ({x.spread_lo:.2f}-{x.spread_hi:.2f})'
B=[A('method','NNLS fit of the native-beam coarse maps (Xb55 9.4x6.2", Xb47 4.3x2.8", Xb4f 6.1x3.7") with Xb4d/Xb4b 3-2 moment-0 templates split into N, S, Bridge, Outer clumps (NE, E, Sext, SWarm, Wclump), diffuse; each template convolved to the native beam of the fitted map'),
   A('assumption','ratio uniform inside each component (component-integrated, aperture radius 1.0-2.5"); same beam filling for all lines of a region; 3% template-mismatch floor added to the noise; errors = ensemble spread over 16 template variants (radius, Xb4d/Xb4b, Wclump assignment); block-bootstrap errors given where noted'),
   A('systematics','14% cross-band flux scale for ladder ratios (not included in ensemble spreads unless stated)')]
EV='scripts/q1_deblend.py -> out/q1/q1_deblend_*.csv'
hn=sv('N','HCN/HCO+ 2-1'); hs=sv('S','HCN/HCO+ 2-1'); fn=sv('N','HCN/HCO+ 4-3'); fs=sv('S','HCN/HCO+ 4-3'); tn=sv('N','HCN/HCO+ 3-2 (Tb) from'); ts=sv('S','HCN/HCO+ 3-2 (Tb) from')
add('Deblended HCN/HCO+ per component at J=2-1 (Band 5, 9.4x6.2"), 3-2 (templates, 1"), 4-3 (Band 7, 4.3x2.8"): N vs S nucleus (Tb, component-integrated)',
    f'N: {rng(hn)} / {rng(tn)} / {rng(fn)}; S: {rng(hs)} / {rng(ts)} / {rng(fs)} (J=2-1 / 3-2 / 4-3; value (16-84% of 16 template variants)). N/S contrast: J=2-1 {NS.iloc[0]["median"]:.2f} (variants {NS.iloc[0].p16:.2f}-{NS.iloc[0].p84:.2f}, but bootstrap errors on the separate ratios are +-0.24 (N) and +-0.38 (S) and the injection test gives a template-mismatch bias factor {CB[(CB.J=="2-1")&(CB.injected_f_per_species==1)].contrast_bias_factor.iloc[0]:.2f} => 2-1 contrast NOT constrained, 1-3 allowed); J=4-3 {NS.iloc[1]["median"]:.2f} ({NS.iloc[1].p16:.2f}-{NS.iloc[1].p84:.2f}; bootstrap errors N +-0.04, S +-0.06 => contrast 1.9+-0.5; injection bias factor {CB[(CB.J=="4-3")&(CB.injected_f_per_species==1)].contrast_bias_factor.iloc[0]:.2f}); J=3-2 1.8 (templates) / 2.0 (peaks). The N>S HCN/HCO+ contrast therefore persists at 4-3 once the N-S pair is separated with the 1" templates (the native Band-7 beam is elongated E-W, minor axis 2.8", so N-S is partly resolved), and declines with J in both nuclei (N 0.69->0.66->0.47, S 0.49->0.36->0.25)',
    'medium',EV+'; q1_deblend_summary.csv, q1_deblend_NS_contrast.csv, q1_deblend_contrast_bias.csv','N, S','see value (ensemble spread; 14% cross-band systematic for the 2-1 and 4-3 entries)',B)
LXv=lambda c,sp,q: LX[(LX.comp==c)&(LX.species==sp)&(LX.quantity==q)].iloc[0]
add('Deblended ladder ratios (Tb) against the more complete Xb4f 3-2: HCN and HCO+ 3-2/2-1 and 4-3/3-2 for N and S',
    'N: HCN 3-2/2-1 %s, 4-3/3-2 %s; HCO+ 3-2/2-1 %s, 4-3/3-2 %s. S: HCN 3-2/2-1 %s (poorly constrained: 2-1 beam), 4-3/3-2 %s; HCO+ 3-2/2-1 %s, 4-3/3-2 %s. Using the Xb4d 3-2 instead (which resolves out 20-50%% relative to Xb4f at N, S: Xb4f/Xb4d = N HCN %.2f HCO+ %.2f, S HCN %.2f HCO+ %.2f) gives higher 4-3/3-2 (N HCN %.2f, HCO+ %.2f; S %.2f, %.2f). N and S ladders are the same within the errors for HCO+ (differences <10%%); HCN 4-3/3-2 is lower at S (0.27 vs 0.40, 1.8 sigma, tentative); all ladders strongly sub-thermal (Tb ratio <<1)'%(
      rng(LXv('N','HCN','3-2 [Xb4f]/2-1 (Tb)')),rng(LXv('N','HCN','4-3/3-2 [Xb4f 3-2] (Tb)')),rng(LXv('N','HCO+','3-2 [Xb4f]/2-1 (Tb)')),rng(LXv('N','HCO+','4-3/3-2 [Xb4f 3-2] (Tb)')),
      rng(LXv('S','HCN','3-2 [Xb4f]/2-1 (Tb)')),rng(LXv('S','HCN','4-3/3-2 [Xb4f 3-2] (Tb)')),rng(LXv('S','HCO+','3-2 [Xb4f]/2-1 (Tb)')),rng(LXv('S','HCO+','4-3/3-2 [Xb4f 3-2] (Tb)')),
      sv('N','3-2(Xb4f)/3-2(Xb4d)').value if False else S[(S.model=='nomissing')&(S.comp=='N')&(S.species=='HCN')&S.quantity.str.contains('recovery')].value.iloc[0],
      S[(S.model=='nomissing')&(S.comp=='N')&(S.species=='HCO+')&S.quantity.str.contains('recovery')].value.iloc[0],
      S[(S.model=='nomissing')&(S.comp=='S')&(S.species=='HCN')&S.quantity.str.contains('recovery')].value.iloc[0],
      S[(S.model=='nomissing')&(S.comp=='S')&(S.species=='HCO+')&S.quantity.str.contains('recovery')].value.iloc[0],
      S[(S.model=='nomissing')&(S.comp=='N')&(S.species=='HCN')&S.quantity.str.startswith('4-3/3-2')].value.iloc[0],S[(S.model=='nomissing')&(S.comp=='N')&(S.species=='HCO+')&S.quantity.str.startswith('4-3/3-2')].value.iloc[0],
      S[(S.model=='nomissing')&(S.comp=='S')&(S.species=='HCN')&S.quantity.str.startswith('4-3/3-2')].value.iloc[0],S[(S.model=='nomissing')&(S.comp=='S')&(S.species=='HCO+')&S.quantity.str.startswith('4-3/3-2')].value.iloc[0]),
    'medium',EV+'; q1_deblend_ladders_xb4f.csv, q1_deblend_summary.csv','N, S','value (16-84% of 16 template variants) +-14% cross-band',B)
I=pd.read_csv(O+'q1_deblend_inject.csv')
def bias(l): x=I[(I.line==l)&np.isclose(I.f_amp,1.0)].iloc[0]; return x.rec_median/x.true_NS_flux_ratio
add('Inject-and-recover test of the deblending: detectability of an N-S ladder difference',
    'Truth built from Xb4b/r=2.0"/Wclump->S templates with the N/S amplitude ratio multiplied by f=1,1.25,1.5,2,3 plus real null-window noise; recovered with the Xb4d/r=1.5" base templates. Noise alone scatters the recovered N/S flux ratio by 3%% (HCN 2-1), 8%% (HCO+ 2-1), 10-20%% (HCN 4-3), 5%% (HCO+ 4-3); template mismatch dominates: recovered/true N/S flux ratio at f=1 is %.2f (HCN 2-1), %.2f (HCO+ 2-1), %.2f (HCN 4-3), %.2f (HCO+ 4-3), %.2f (CS 7-6). The response to injected differences is monotonic (HCN 2-1: f=1.25,1.5,2,3 -> recovered/recovered(f=1) = 1.23, 1.46, 1.89, 2.70), so factor-1.25 changes are visible in the same line, but a species ratio (e.g. HCN/HCO+ 2-1) can be biased by a factor %.2f (2-1) or %.2f (4-3). Minimum detectable N-S difference in a ladder ratio: ~30-40%% (cross-band 14%% x sqrt2 and ensemble spread), a 2-1 N-S HCN/HCO+ contrast is not measurable (N and S amplitudes correlated, corr ~0.8)'%(bias('HCN 2-1'),bias('HCO+ 2-1'),bias('HCN 4-3'),bias('HCO+ 4-3'),bias('CS 7-6'),CB[(CB.J=='2-1')&(CB.injected_f_per_species==1)].contrast_bias_factor.iloc[0],CB[(CB.J=='4-3')&(CB.injected_f_per_species==1)].contrast_bias_factor.iloc[0]),
    'medium',EV+'; q1_deblend_inject.csv, q1_deblend_contrast_bias.csv',None,'see value',B)
cs=lambda c,sp: S[(S.model=='nomissing')&(S.comp==c)&(S.species==sp)&S.quantity.str.startswith('CS 7-6')].iloc[0]
add('CS 7-6 per component relative to HCO+ 3-2 and HCN 3-2 (Tb, Band 7 native beam deblended)',
    'CS 7-6/HCO+ 3-2: N %s, S %s, Bridge %s; CS 7-6/HCN 3-2: N %s, S %s, Bridge %s. CS 7-6 scales with HCO+ (N=S within errors) and not with HCN (S/N 1.9): same conclusion as the blended 6.5" aperture ratios but now per nucleus. Outer clumps: not detected (0 in the NNLS fit)'%(rng(cs('N','HCO+')),rng(cs('S','HCO+')),rng(cs('Bridge','HCO+')),rng(cs('N','HCN')),rng(cs('S','HCN')),rng(cs('Bridge','HCN'))),
    'medium',EV+'; q1_deblend_summary.csv','N, S, Bridge','ensemble 16-84%',B)
add('HCN/H13CN 4-3 lower limits per region (carried from p0001, scripts/h13cn.py) and implied opacity bound',
    'HCN/H13CN > 9.1 (N), > 6.7 (S), > 6.7 (Bridge) (best-chi2 log-cubic wing model, 341.80-342.20 GHz, 3 sigma); range over accepted wing models 6.7-11.8 (N), 1.7-7.4 (S), 3.8-13.3 (Bridge). For 12C/13C = 30/50/90, HCN/H13CN > 9.5 corresponds to tau(HCN 4-3) <= 3.2/5.5/10 and > 2.3 to <= 17/29/51 (q1_h13cn_tau_bound.csv): N is not highly opaque in HCN 4-3, the S and Bridge limits are weaker. The limits depend on the CO-wing family (p0001)',
    'low','out/h13cn_limits.csv (p0001); scripts/q1_radex.py -> out/q1/q1_h13cn_tau_bound.csv','N, S, Bridge','3 sigma',[A('12C/13C','30, 50, 90 (assumed)')])
W=pd.read_csv(O+'q1_ratio_windows.csv'); Pf=pd.read_csv(O+'q1_line_profiles.csv')
def w(reg,win): x=W[(W.region==reg)&(W.window==win)].iloc[0]; return x.R
add('Window-width and line-profile systematics of HCN/HCO+ 3-2 (Tb, 1.05" Xb4d): +-200, +-350, +-500 km/s (raw and with the HCN v2=1f channels removed)',
    'N %.3f / %.3f / %.3f (raw) / %.3f (v2=1f cut); S %.3f / %.3f / %.3f / %.3f; Bridge %.3f / %.3f / %.3f / %.3f; Wclump %.3f / %.3f / %.3f / %.3f. Window truncation changes the nuclear ratios by <=1.5%% (N), <=2.5%% (S) -- much smaller than the +-5%% assumed; the N/S contrast is %.2f (+-200), %.2f (+-350), %.2f (+-500). HCN v2=1f 3-2 (267.199 GHz) sits at +401 km/s (redshifted) in the HCO+ frame, not -400 as assumed in p0001/lib comments; its effect on the +-500 km/s ratio is <=0.5%%. HCN and HCO+ profiles at N, S, Bridge, Wclump have the same peak velocity (within 5 km/s) and half-maximum width within channel resolution; no absorption dip (minimum within the line >= -3.7 sigma over ~70 channels) in either line'%(
     w('N','+-200'),w('N','+-350'),w('N','+-500 (raw)'),w('N','+-500 minus v2=1f channels'),w('S','+-200'),w('S','+-350'),w('S','+-500 (raw)'),w('S','+-500 minus v2=1f channels'),
     w('Bridge','+-200'),w('Bridge','+-350'),w('Bridge','+-500 (raw)'),w('Bridge','+-500 minus v2=1f channels'),w('Wclump','+-200'),w('Wclump','+-350'),w('Wclump','+-500 (raw)'),w('Wclump','+-500 minus v2=1f channels'),
     w('N','+-200')/w('S','+-200'),w('N','+-350')/w('S','+-350'),w('N','+-500 (raw)')/w('S','+-500 (raw)')),
    'high','scripts/q1_velratio.py -> out/q1/q1_ratio_windows.csv, q1_line_profiles.csv, q1_velratio.log','N, S, Bridge, Wclump','statistical <=0.01; window systematic <=2.5%',None)
Bn=pd.read_csv(O+'q1_ratio_vs_velocity.csv')
def bv(reg,lo): x=Bn[(Bn.region==reg)&(Bn.v_lo==lo)]; return x.iloc[0].R if len(x) and np.isfinite(x.iloc[0].R) else np.nan
add('HCN/HCO+ 3-2 (Tb) as a function of velocity in 50 km/s bins (1.05", Xb4d) at N, S, Bridge',
    'N: %s ; S: %s ; Bridge: %s (bins from -150 to +200 km/s relative to 2780; only bins with both lines >3 sigma). Core (|dv|<100): N 0.79-0.84 (flat), S 0.36-0.41 (flat), Bridge 0.31-0.50; N/S = 2.0-2.2 in every core bin. The high ratios in the red wing (N 1.27, 1.88 at +100..+200 km/s) come from 1-2 mJy/beam excess in the HCN spectrum at +150..+250 km/s, where CH3NH2 lines at 263.28-263.29 GHz fall (HCN is 0.4-1 mJy above HCO+ in a region where HCO+ is ~0), and the HCO+ red wing is faint; they contribute <1%% of the flux. The blue-wing ratios are not measurable at N, S (wings <3 sigma)'%(
     ' '.join('%+d:%.2f'%(lo,bv('N',lo)) for lo in range(-200,201,50) if np.isfinite(bv('N',lo))),' '.join('%+d:%.2f'%(lo,bv('S',lo)) for lo in range(-250,201,50) if np.isfinite(bv('S',lo))),' '.join('%+d:%.2f'%(lo,bv('Bridge',lo)) for lo in range(-150,201,50) if np.isfinite(bv('Bridge',lo)))),
    'medium','scripts/q1_velratio.py, q1_redwing_check.py -> out/q1/q1_ratio_vs_velocity.csv, q1_redwing_profiles.csv','N, S, Bridge','bins: statistical 3-10%',[A('bins','50 km/s, values relative to 2780 km/s (radio, LSRK)'),A('spectra','pbcor Xb4d cubes convolved to 1.05" circular beam, value at the position; channel noise from |v-2780|>700 km/s (MAD)')])
G=pd.read_csv(O+'q1_soutflow_gauss.csv'); Wv=pd.read_csv(O+'q1_soutflow_wing_variants.csv'); gr=G.iloc[-1]
xd=Wv[Wv.set=='Xb4d 1.05"']; xb=Wv[Wv.set=='Xb4b->1.05" Soutflow']
add('Soutflow wing HCN/HCO+ 3-2 (Tb): noise treatment, window dependence, Xb4b check and two-Gaussian decomposition',
    f'Xb4d 1.05" point values, blue windows 2272-2572 / 2300-2500 / 2200-2600 / 2350-2550: {xd.R.iloc[0]:.2f}+-{xd.eR.iloc[0]:.2f} (HCN {xd.snr_HCN.iloc[0]:.1f} sigma, HCO+ {xd.snr_HCO.iloc[0]:.1f} sigma) / {xd.R.iloc[1]:.2f}+-{xd.eR.iloc[1]:.2f} (HCO+ {xd.snr_HCO.iloc[1]:.1f} sigma) / {xd.R.iloc[2]:.2f}+-{xd.eR.iloc[2]:.2f} / {xd.R.iloc[3]:.2f}+-{xd.eR.iloc[3]:.2f}. Noise = channel rms from |v-2780|>700 km/s (MAD, 0.76-0.85 mJy/beam per 4.4 km/s channel at Soutflow) x sqrt(N_chan). Xb4b convolved to 1.05": {xb.R.iloc[0]:.2f}+-{xb.eR.iloc[0]:.2f} / {xb.R.iloc[1]:.2f}+-{xb.eR.iloc[1]:.2f} / {xb.R.iloc[2]:.2f}+-{xb.eR.iloc[2]:.2f} (HCO+ only {xb.snr_HCO.iloc[0]:.1f}, {xb.snr_HCO.iloc[1]:.1f}, {xb.snr_HCO.iloc[2]:.1f} sigma). Two-Gaussian (core + blue wing) fits to each spectrum (chi2_r ~1) with residual bootstrap (300): wing HCN/HCO+ = {gr.core_amp_mJy:.2f} (16-84%: {gr.core_v:.2f}-{gr.core_sigma:.2f}), core component {gr.wing_amp_mJy:.2f} ({gr.wing_v:.2f}-{gr.wing_sigma:.2f}); the box-window values (1.7) are inflated by core leakage into the 2272-2572 window. Same windows at N, S: wing not detected in either line (<2 sigma). Matched aperture: all values are at the 1.05" beam, same as the nuclei. Best statement: blue-wing HCN/HCO+ at the Soutflow position is 1.2-1.8 (central 1.5+-0.3), 2-4x the local core component (0.49) and the S nucleus (0.40), and higher than the N nucleus; the full +-350 window gives only 0.75+-0.06 (0.62 for +-200, 0.77-0.80 for +-500). Candidate: single position, HCO+ wing only 5-7 sigma, the CO-wing model of Q0 and outflow association untested',
    'low','scripts/q1_velratio.py -> out/q1/q1_soutflow_wing_variants.csv, q1_soutflow_gauss.csv','Soutflow (candidate)','ratio 1.2-1.8 (systematic range of estimators) +-0.3 (statistical)',[A('v2=1f','HCN v2=1f at +401 km/s in the HCO+ frame: outside blue windows'),A('Gaussian model','core (centre free +-150 km/s of 2722, sigma 20-300) + wing (centre 100-600 km/s blue, sigma 40-300)')])
Dd=pd.read_csv(O+'q1_disk_deficit_interpretation.csv',keep_default_na=False); DD=pd.read_csv(O+'q1_disk_double_ratio.csv',keep_default_na=False); M=pd.read_csv(O+'q1_disk_recovery_model.csv')
dg=lambda sp,zl,col: Dd[(Dd.species==sp)&(Dd.zero_level==zl)].iloc[0][col]
add('Disk 3-2 deficit: resolved-out flux vs low excitation (parametric uv-hole model, Band 5 2-1 vs Band 6 Xb4f 3-2)',
    'Disk-mask 3-2/2-1 (Tb) relative to the compact (N, S, deblended and 10" matched) value: HCO+ %.2f (no zero-level correction) / %.2f (ring correction) [%.3f vs %.3f]; HCN %.2f / %.2f [%.3f vs %.3f]. A Gaussian disk of FWHM th loses a fraction of its brightness exp[-(pi th B_min/lambda)^2/(4 ln2)] with B_min = 8.7 m (7-m array shadowing; both maps have B_max ~ lambda/theta_maj ~ 40 m, i.e. compact-array-like beams): deficit 0.76/0.67/0.58/0.49/0.33/0.18 for th = 10/12/14/16/20/25" (B_min 15 m: 0.44/0.31/0.20/0.12/0.04/0.006); the HCO+ deficit is reproduced by th = %.0f-%.0f" (B_min 8.7 m) or %.0f-%.0f" (15 m) -- a natural scale for the structure in the mask -- so the HCO+ disk deficit is fully consistent with the same excitation as the nuclei plus missing short spacings in Xb4f (MRS ~26" at 1.1 mm vs ~40" at 1.7 mm for B_min 8.7 m). Not consistent with the model alone: HCN (deficit %.2f without correction, th=%.0f-%.0f" needed) and the double ratio (HCN/HCO+ 3-2)/(HCN/HCO+ 2-1) = %.2f (none) / %.2f (ring) in the disk vs 0.77 (N) and 0.76 (S) at 10": if HCN and HCO+ share distribution and recovery this double ratio is recovery-independent, so the disk HCN 3-2 is weak relative to HCO+ 3-2 (or HCN is more compact) -- but its value depends entirely on the ring zero level (0.13 vs 0.54). The robust disk number is HCN/HCO+ 2-1 = 0.47-0.50 (+-0.01 stat, +-0.03 zero level) vs 0.62 (N), 0.56 (S) at the same 10" beam, i.e. 15-25%% lower; the disk 3-2 ratio is reported only as a lower limit in recovery (HCO+ 3-2/2-1 >= 0.265-0.287 true ratio)'%(
      dg('HCO+','none','deficit_obs'),dg('HCO+','ring','deficit_obs'),dg('HCO+','none','disk_ratio'),dg('HCO+','none','compact_ratio'),dg('HCN','none','deficit_obs'),dg('HCN','ring','deficit_obs'),dg('HCN','none','disk_ratio'),dg('HCN','none','compact_ratio'),
      dg('HCO+','ring','theta_FWHM_for_deficit_B8.7'),dg('HCO+','none','theta_FWHM_for_deficit_B8.7'),dg('HCO+','ring','theta_FWHM_for_deficit_B15.0'),dg('HCO+','none','theta_FWHM_for_deficit_B15.0'),
      dg('HCN','none','deficit_obs'),dg('HCN','ring','theta_FWHM_for_deficit_B8.7'),dg('HCN','none','theta_FWHM_for_deficit_B8.7'),DD.iloc[0].double_ratio_disk,DD.iloc[1].double_ratio_disk),
    'low','scripts/q1_disk_model.py -> out/q1/q1_disk_recovery_model.csv, q1_disk_deficit_interpretation.csv, q1_disk_double_ratio.csv; scripts/q1_disk.py','Disk (candidate)','th ranges from the +-0.04 spread of the compact ratio',
    [A('array','B_min = 8.7 m or 15 m, B_max ~ 40 m inferred from beam size (not in headers: image products only)'),A('model','single Gaussian disk, uv hole only; the nested Xb4b->Xb4d->Xb4f recovery (HCO+ r<10": 0.34, 0.53, 1) is the empirical counterpart')])
